<?php
declare(strict_types=1);
require_once __DIR__ . '/../config/auth.php';
require_once __DIR__ . '/../config/telefono.php';
require_once __DIR__ . '/../config/reglas-acceso.php';
page_require(['ADMIN','VERIFICADOR']);
$config = require __DIR__ . '/../config/database.php';
$pdo = new PDO("mysql:host={$config['host']};dbname={$config['dbname']};charset={$config['charset']}",$config['user'],$config['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$id = trim((string)filter_input(INPUT_GET, 'id', FILTER_DEFAULT));
if (!preg_match('/^[a-f0-9-]{36}$/i', $id)) { http_response_code(400); exit('Alumno no especificado.'); }
$sedeClave=auth_active_sede_clave();
$stmt=$pdo->prepare("SELECT id FROM sedes WHERE clave=:clave AND activo=1 LIMIT 1");
$stmt->execute([':clave'=>$sedeClave]);
$sedeId=(string)$stmt->fetchColumn();
if($sedeId===''){http_response_code(422);exit('Sede activa inválida.');}
$sql = "SELECT a.id,a.nombre,a.fecha_nacimiento,a.whatsapp,a.correo,a.fecha_inicio,a.estado_administrativo,a.observaciones,h.hora_inicio,h.hora_fin,p.nombre AS plan_nombre,p.sesiones_semana,p.precio FROM alumnos a LEFT JOIN horarios h ON h.id=a.horario_preferido_id AND h.sede_id=a.sede_id LEFT JOIN planes p ON p.id=a.plan_actual_id AND p.sede_id=a.sede_id WHERE a.id=:id AND a.sede_id=:sede LIMIT 1";
$stmt=$pdo->prepare($sql);$stmt->execute([':id'=>$id,':sede'=>$sedeId]);$alumno=$stmt->fetch();if(!$alumno){http_response_code(404);exit('Alumno no encontrado.');}
$historica=regla_inscripcion_historica_cubierta($pdo,(string)$alumno['id']);
function e(?string $valor):string{return htmlspecialchars($valor??'',ENT_QUOTES,'UTF-8');}
function fecha(?string $valor):string{return !empty($valor)?date('d/m/Y',strtotime($valor)):'—';}
function hora(?string $valor):string{return !empty($valor)?date('H:i',strtotime($valor)):'—';}
function telefono_visible(?string $valor):string{
    $v=trim((string)$valor);if($v==='')return '—';
    if(!telefono_es_e164($v))return $v.' · país sin verificar';
    $d=telefono_descomponer($v);$p=telefono_paises();$codigo=$d['pais']!==''?($p[$d['pais']]['codigo']??''):'';
    return $codigo!==''?$codigo.' '.$d['nacional']:$v;
}
?>
<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>Ficha de <?=e($alumno['nombre'])?></title><style>*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#f3f6fa;color:#172033}.contenedor{max-width:900px;margin:0 auto;padding:30px 20px}.encabezado{margin-bottom:25px}.encabezado a{color:#2563eb;text-decoration:none;font-size:14px}.encabezado h1{margin:12px 0 5px;font-size:30px}.subtitulo{color:#64748b}.tarjeta{background:white;border-radius:18px;padding:25px;margin-bottom:18px;box-shadow:0 4px 18px rgba(0,0,0,.06)}.titulo{font-size:18px;font-weight:bold;margin-bottom:20px}.datos{display:grid;grid-template-columns:repeat(2,1fr);gap:18px}.dato{padding:14px;background:#f8fafc;border-radius:10px}.etiqueta{display:block;font-size:12px;color:#64748b;margin-bottom:5px}.valor{font-size:16px;font-weight:600}.estado{display:inline-block;padding:6px 12px;border-radius:999px;font-size:13px;font-weight:bold}.activo{background:#dcfce7;color:#166534}.baja{background:#fee2e2;color:#991b1b}.historica{background:#e0f2fe;color:#075985}.observaciones{white-space:pre-wrap;line-height:1.6;color:#475569}.acciones{margin-top:15px}.boton-editar{display:inline-block;padding:10px 16px;background:#2563eb;color:white!important;border-radius:10px;text-decoration:none!important;font-weight:600}@media(max-width:650px){.datos{grid-template-columns:1fr}.encabezado h1{font-size:25px}.tarjeta{padding:18px}}</style></head><body><div class="contenedor"><div class="encabezado"><a href="alumnos.php">← Volver a alumnos</a><div class="acciones"><a class="boton-editar" href="editar-alumno.php?id=<?=urlencode($alumno['id'])?>">Editar alumno</a></div><h1><?=e($alumno['nombre'])?></h1><div class="subtitulo">Ficha del alumno · ID <?=e((string)$alumno['id'])?></div></div><div class="tarjeta"><div class="titulo">Información personal</div><div class="datos"><div class="dato"><span class="etiqueta">Nombre</span><span class="valor"><?=e($alumno['nombre'])?></span></div><div class="dato"><span class="etiqueta">Fecha de nacimiento</span><span class="valor"><?=fecha($alumno['fecha_nacimiento'])?></span></div><div class="dato"><span class="etiqueta">WhatsApp</span><span class="valor"><?=e(telefono_visible($alumno['whatsapp']))?></span></div><div class="dato"><span class="etiqueta">Correo</span><span class="valor"><?=e($alumno['correo'])?:'—'?></span></div></div></div><div class="tarjeta"><div class="titulo">Información de natación</div><div class="datos"><div class="dato"><span class="etiqueta">Fecha de inicio</span><span class="valor"><?=fecha($alumno['fecha_inicio'])?></span></div><div class="dato"><span class="etiqueta">Horario</span><span class="valor"><?=hora($alumno['hora_inicio'])?> — <?=hora($alumno['hora_fin'])?></span></div><div class="dato"><span class="etiqueta">Plan</span><span class="valor"><?=e($alumno['plan_nombre'])?:'—'?></span></div><div class="dato"><span class="etiqueta">Sesiones por semana</span><span class="valor"><?=$alumno['sesiones_semana']!==null?e((string)$alumno['sesiones_semana']):'—'?></span></div><div class="dato"><span class="etiqueta">Precio</span><span class="valor"><?=$alumno['precio']!==null?'$'.number_format((float)$alumno['precio'],0):'—'?></span></div><div class="dato"><span class="etiqueta">Estado</span><span class="estado <?=$alumno['estado_administrativo']==='ACTIVO'?'activo':'baja'?>"><?=e($alumno['estado_administrativo'])?></span></div><div class="dato"><span class="etiqueta">Inscripción</span><?php if($historica):?><span class="estado historica">HISTÓRICA CUBIERTA</span><?php else:?><span class="valor">Según pagos registrados</span><?php endif;?></div></div></div><div class="tarjeta"><div class="titulo">Observaciones</div><div class="observaciones"><?=e($alumno['observaciones'])?:'Sin observaciones.'?></div></div></div></body></html>
